function Hashtag(){const {tag}=useParams();return <div className="content"><div className="hashtag-hero"><span className="hashtag-symbol">#</span><div><h1>#{tag}</h1><p>Discover moments shared by the ROVE community.</p><small>Community discovery</small></div><Button onClick={e=>{e.currentTarget.textContent='Following hashtag'}}>Follow hashtag</Button></div><div className="tabs"><button className="selected">Top</button><button>Recent</button></div><div className="photo-grid">{[...pics,...pics].map((p,i)=><Link className="photo-tile" to={`/post/${i%3+1}`} key={p+i}><img src={img(p,500)}/></Link>)}</div></div>}
function PostDetail(){const {id}=useParams();const [post,setPost]=useState<any>(null),[comments,setComments]=useState<any[]>([]),[comment,setComment]=useState(''),[liked,setLiked]=useState(false),[likeCount,setLikeCount]=useState(0),[saved,setSaved]=useState(false),[msg,setMsg]=useState(''),[busy,setBusy]=useState(false);useEffect(()=>{let live=true;api(`/posts/${id}/`).then(p=>{if(!live)return;setPost(p);setLiked(!!p.is_liked);setLikeCount(Number(p.likes_count||0));setSaved(!!p.is_bookmarked)}).catch(e=>{if(live)setMsg(e.message||'Could not load this post.')});api(`/posts/${id}/comments/`).then(c=>{if(live)setComments(Array.isArray(c)?c:[])}).catch(()=>{});return()=>{live=false}},[id]);const toggleLike=async()=>{if(busy)return;setBusy(true);setMsg('');try{const r=await api(`/posts/${id}/like/`,{method:'POST'});setLiked(!!r.liked);setLikeCount(Number(r.likes_count||0))}catch(e:any){setMsg(e.message||'Could not like post.')}finally{setBusy(false)}};const addComment=async(e:any)=>{e.preventDefault();if(!comment.trim())return;try{const c=await api(`/posts/${id}/comments/`,{method:'POST',body:JSON.stringify({text:comment.trim()})});setComments(prev=>[...prev,c]);setComment('');setPost((prev:any)=>({...prev,comments_count:Number(prev?.comments_count||0)+1}))}catch(e:any){setMsg(e.message||'Could not add comment.')}};const toggleSave=async()=>{try{const r=await api(`/posts/${id}/bookmark/`,{method:'POST'});setSaved(!!r.bookmarked)}catch(e:any){setMsg(e.message||'Could not save post.')}};if(!post)return <div className="content"><Link to="/" className="back-link"><ArrowLeft size={16}/> Back to feed</Link>{msg?<div className="panel empty-state">{msg}</div>:<div className="muted">Loading post…</div>}</div>;return <div className="content"><Link to="/" className="back-link"><ArrowLeft size={16}/> Back to feed</Link><div className="detail-layout"><img className="detail-image" src={post.image||img(pics[0])} alt={post.caption||'Post image'}/><section className="detail-side"><div className="post-author"><Avatar src={post.avatar}/><div className="author-meta"><b>{post.username}</b><small>{post.location||'ROVE community'}</small></div><Link className="icon-btn push" to={`/post/${id}/edit`} aria-label="Edit post"><MoreHorizontal/></Link></div><div className="detail-caption"><b>{post.username}</b> {post.caption}</div><div className="comment-list">{comments.length?comments.map((c:any)=><div key={c.id}><Avatar size={32} src={c.avatar||img(pics[9],100)}/><p><b>{c.username}</b> {c.text}<small>{c.created_at?new Date(c.created_at).toLocaleString():''}</small></p></div>):<div className="empty-state">No comments yet. Be the first to comment.</div>}</div><div className="detail-actions"><button className={'icon-btn '+(liked?'liked':'')} onClick={toggleLike} aria-label={liked?'Unlike post':'Like post'}><Heart fill={liked?'currentColor':'none'}/></button><button className="icon-btn" onClick={()=>document.querySelector<HTMLInputElement>('.message-compose input')?.focus()} aria-label="Write comment"><MessageSquare/></button><button className="icon-btn" onClick={()=>location.assign(`/post/${id}/share`)} aria-label="Share post"><Share2/></button><button className={'icon-btn push '+(saved?'saved':'')} onClick={toggleSave} aria-label={saved?'Unsave post':'Save post'}><Bookmark fill={saved?'currentColor':'none'}/></button><b>{likeCount.toLocaleString()} likes</b>{liked&&<span className="liked-label">You liked this</span>}</div>{msg&&<p className="error-text" style={{padding:'0 16px'}}>{msg}</p>}<form className="message-compose" onSubmit={addComment}><input value={comment} onChange={e=>setComment(e.target.value)} placeholder="Add a comment…" aria-label="Add a comment"/><button type="submit" className="text-btn" disabled={!comment.trim()}>Post</button></form></section></div></div>}
function EditPost(){const {id}=useParams();const [caption,setCaption]=useState('A little moment worth remembering. ✨ #rove'),[locationText,setLocationText]=useState('Dolomites, Italy'),[msg,setMsg]=useState('');return <div className="content narrow-content"><PageHeader title="Edit post" subtitle="Update the details of your post."/><div className="create-card"><img className="edit-post-image" src={img(pics[0])}/><label className="field"><span>Caption</span><textarea value={caption} onChange={e=>setCaption(e.target.value)}/></label><label className="field"><span>Location</span><input value={locationText} onChange={e=>setLocationText(e.target.value)}/></label>{msg&&<p className="success-text">{msg}</p>}<div className="form-actions"><Button variant="secondary" onClick={()=>location.assign(`/post/${id}`)}>Cancel</Button><Button onClick={async()=>{try{await api(`/posts/${id}/`,{method:'PATCH',body:JSON.stringify({caption,location:locationText})});setMsg('Changes saved.')}catch(e:any){setMsg(e.message)}}}>Save changes</Button></div></div></div>}
